# [CAT 6] PHYSICS: Material Density Checks
HEAVY_MATERIALS = r'(?i)\b(?:STEEL|IRON|METAL|MACHINERY|ENGINE|GRANITE|STONE|MARBLE|LEAD|COPPER)\b'
LIGHT_MATERIALS = r'(?i)\b(?:TEXTILE|COTTON|PLASTIC|TOY|PAPER|FOAM|CLOTHING|APPAREL|FEATHER|DOWN)\b'


# ==========================================
# 2. UTILITY FUNCTIONS
# ==========================================
def clean_text_field(text):
    if pd.isna(text): return ""
    text = str(text)
    text = html.unescape(text) # Decode HTML entities
    text = re.sub(r'<[^>]+>', ' ', text) # Remove HTML tags
    text = text.replace('\n', ' ').replace('\r', ' ').replace('\t', ' ')
    text = re.sub(r'\s+', ' ', text).strip()
    return text

def get_snippet_and_match(text, pattern, window=40):
    """
    Returns text trimmed to 'window' characters around the keyword match,
    AND the specific keyword that triggered the match.
    """
    if pd.isna(text): return "", "N/A"
    text = str(text)
    
    if not pattern: 
        return (text[:85] + "..." if len(text) > 85 else text), "N/A"

    try:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            start = max(0, match.start() - window)
            end = min(len(text), match.end() + window)
            prefix = "..." if start > 0 else ""
            suffix = "..." if end < len(text) else ""
            snippet = f"{prefix}{text[start:end]}{suffix}"
            matched_word = match.group(0) # Get the exact word that triggered it
            return snippet, matched_word
    except Exception:
        pass
    
    return (text[:85] + "..." if len(text) > 85 else text), "N/A"

# ==========================================
# 3. MAIN EXECUTION
# ==========================================
def run_analysis():
    filename = 're.csv'
    print(f"--- [STEP 1] Loading Data: {filename} ---")
    
    if not os.path.exists(filename):
        print(f"\n[ERROR] File '{filename}' not found.")
        return

    try:
        df = pd.read_csv(filename, on_bad_lines='skip')
        
        # Filter garbage if column exists
        if 'Status' in df.columns:
            df_clean = df[df['Status'] != 'Unknown Page Structure'].copy()
        else:
            df_clean = df.copy()
        
        if 'Goods Description' not in df_clean.columns:
            print("[ERROR] 'Goods Description' column missing.")
            return

        df_clean['Goods Description'] = df_clean['Goods Description'].apply(clean_text_field)
        print(f"Loaded {len(df_clean)} rows.")
        
    except Exception as e:
        print(f"[CRITICAL ERROR] Failed loading file: {e}")
        return

    # --- FALSE POSITIVE SCRUBBING ---
    print("--- [STEP 1.5] Scrubbing False Positives ---")
    clothing_context = r'(?i)(top|shirt|knitting|lady|women|apparel)'
    mask_tank = df_clean['Goods Description'].str.contains(r'(?i)\btank\b', na=False, regex=True)
    mask_clothing = df_clean['Goods Description'].str.contains(clothing_context, na=False, regex=True)
    df_clean['IS_CLOTHING_TANK'] = mask_tank & mask_clothing
    df_clean['IS_BRAND_NAME'] = df_clean['Goods Description'].str.contains(r'(?i)good things', na=False, regex=True)

    # --- METADATA EXTRACTION ---
    print("--- [STEP 2] Extracting Metrics ---")
    def extract_metrics(text):
        text_upper = str(text).upper()
        w = re.search(r'(\d{1,3}(?:,\d{3})*(?:\.\d+)?|\d+(?:\.\d+)?)\s*(?:KGS?|KILOS?)', text_upper)
        weight = float(w.group(1).replace(',', '')) if w else None
        v = re.search(r'(\d{1,3}(?:,\d{3})*(?:\.\d+)?|\d+(?:\.\d+)?)\s*(?:CBM|M3)', text_upper)
        volume = float(v.group(1).replace(',', '')) if v else None
        un = re.search(r'UN\s*(\d{4})', text_upper)
        un_num = un.group(1) if un else None
        return pd.Series([weight, volume, un_num])

    df_clean[['Extracted_Weight', 'Extracted_Volume', 'UN_Number']] = df_clean['Goods Description'].apply(extract_metrics)
    df_clean['Density'] = df_clean['Extracted_Weight'] / df_clean['Extracted_Volume']
    
    if 'Pieces' in df_clean.columns:
        df_clean['Pieces'] = pd.to_numeric(df_clean['Pieces'], errors='coerce').fillna(1)
    else:
        df_clean['Pieces'] = 1

    # --- SCANNERS ---
    print("--- [STEP 3] Running Scanners ---")
    
    # Security
    alert_security = df_clean[(df_clean['Goods Description'].str.contains(SECURITY_KEYWORDS, regex=True, na=False)) & (df_clean['IS_CLOTHING_TANK'] == False)]
    alert_narcotics = df_clean[df_clean['Goods Description'].str.contains(NARCOTICS_KEYWORDS, regex=True, na=False)]

    # Revenue
    alert_revenue = df_clean[df_clean['Goods Description'].str.contains(REVENUE_RISK_KEYWORDS, regex=True, na=False)]
    alert_luxury = df_clean[df_clean['Goods Description'].str.contains(LUXURY_KEYWORDS, regex=True, na=False)]
    alert_counterfeit = df_clean[df_clean['Goods Description'].str.contains(COUNTERFEIT_KEYWORDS, regex=True, na=False)]

    # Safety
    alert_undeclared_dg = df_clean[(df_clean['Goods Description'].str.upper().str.contains(DG_KEYWORDS, regex=True)) & (df_clean['UN_Number'].isna()) & (~df_clean['Goods Description'].str.upper().str.contains('NON-HAZ|NON HAZ|NOT RESTRICTED'))]
    alert_waste = df_clean[df_clean['Goods Description'].str.contains(WASTE_KEYWORDS, regex=True, na=False)]

    # Bio
    alert_bio = df_clean[df_clean['Goods Description'].str.contains(BIOSAFETY_KEYWORDS, regex=True, na=False)]

    # Oddities
    alert_weird = df_clean[df_clean['Goods Description'].str.contains(WEIRD_KEYWORDS, regex=True, na=False)]
    alert_manual = df_clean[(df_clean['Goods Description'].str.contains(CONVERSATIONAL_KEYWORDS, regex=True, na=False)) & (df_clean['IS_BRAND_NAME'] == False)]
    alert_shouting = df_clean[df_clean['Goods Description'].str.contains(SHOUTING_KEYWORDS, regex=True, na=False)]
    
    # Physics
    alert_physics_light = df_clean[(df_clean['Goods Description'].str.contains(HEAVY_MATERIALS, regex=True)) & (df_clean['Density'] < 200)]
    alert_physics_heavy = df_clean[(df_clean['Goods Description'].str.contains(LIGHT_MATERIALS, regex=True)) & (df_clean['Density'] > 1000)]

    # --- OUTPUT GENERATION ---
    print("\n" + "="*110)
    print(f"{'ADVANCED CARGO RISK REPORT (With Context Snippets)':^110}")
    print("="*110)

    def print_category(title, df_sub, pattern=None):
        if df_sub.empty: return
        print(f"\n>> {title} [{len(df_sub)} matches]")
        print(f"   {'Tracking #':<15} | {'Match':<15} | {'Context Snippet'}")
        print(f"   {'-'*15} | {'-'*15} | {'-'*60}")
        
        has_tracking = 'Tracking Number' in df_sub.columns
        for idx, row in df_sub.head(600).iterrows():
            desc = row['Goods Description']
            snippet, matched_word = get_snippet_and_match(desc, pattern, window=35)
            tracking = str(row['Tracking Number']) if has_tracking else f"Row {idx}"
            print(f"   {tracking:<15} | {matched_word:<15} | {snippet}")

    print("\n--- [SECURITY & PROHIBITED] ---")
    print_category("WEAPONS / TACTICAL / SMUGGLING", alert_security, SECURITY_KEYWORDS)
    print_category("NARCOTICS / CHEMICALS", alert_narcotics, NARCOTICS_KEYWORDS)

    print("\n--- [REVENUE & COMPLIANCE] ---")
    print_category("UNDERVALUATION (NCV/Samples)", alert_revenue, REVENUE_RISK_KEYWORDS)
    print_category("LUXURY / HIGH VALUE", alert_luxury, LUXURY_KEYWORDS)
    print_category("COUNTERFEIT INDICATORS", alert_counterfeit, COUNTERFEIT_KEYWORDS)

    print("\n--- [SAFETY & HAZMAT] ---")
    print_category("UNDECLARED DG (No UN#)", alert_undeclared_dg, DG_KEYWORDS)
    print_category("WASTE / SCRAP", alert_waste, WASTE_KEYWORDS)

    print("\n--- [BIOSAFETY & RESTRICTED] ---")
    print_category("WILDLIFE / BIO / HUMAN REMAINS", alert_bio, BIOSAFETY_KEYWORDS)

    print("\n--- [CURIOSITY & ODDITIES] ---")
    print_category("BIZARRE / FUNNY / WEIRD", alert_weird, WEIRD_KEYWORDS)
    print_category("CONVERSATIONAL / MANUAL INPUT", alert_manual, CONVERSATIONAL_KEYWORDS)
    print_category("SHOUTING (!!/??)", alert_shouting, SHOUTING_KEYWORDS)

    print("\n--- [PHYSICS ANOMALIES] ---")
    print_category("SUSPICIOUSLY LIGHT (Hollow?)", alert_physics_light, None)
    print_category("SUSPICIOUSLY HEAVY (Hidden?)", alert_physics_heavy, None)

if __name__ == "__main__":
    run_analysis()
